import sys

def main():
    s = sys.stdin.read().split()[0]

    def pal(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            print('true' if pal(i + 1, j) or pal(i, j - 1) else 'false')
            return
        i += 1
        j -= 1
    print('true')

